import React from 'react';
import { useTranslation } from 'react-i18next';

export default function Controls({
  provinces, selectedProvinces, onChangeProvinces,
  foodTypes, selectedFoodType, onChangeFoodType,
  dateRange, onChangeDateRange
}) {
  const { t } = useTranslation();

  return (
    <div style={{ margin: '1rem 0' }}>
      <label>
        {t('select_food_type')}:
        <select value={selectedFoodType} onChange={e => onChangeFoodType(e.target.value)}>
          {foodTypes.map(type => (
            <option key={type} value={type}>{type}</option>
          ))}
        </select>
      </label>

      <label style={{ marginLeft: 20 }}>
        {t('select_provinces')}:
        <select multiple value={selectedProvinces} onChange={e =>
          onChangeProvinces(Array.from(e.target.selectedOptions, o => o.value))
        }>
          {provinces.map(prov => (
            <option key={prov} value={prov}>{prov}</option>
          ))}
        </select>
      </label>

      <label style={{ marginLeft: 20 }}>
        {t('select_date_range')}:
        <input type="month" value={dateRange.start} onChange={e => onChangeDateRange({ ...dateRange, start: e.target.value })} />
        —
        <input type="month" value={dateRange.end} onChange={e => onChangeDateRange({ ...dateRange, end: e.target.value })} />
      </label>
    </div>
  );
}
